    # Iterate over the beads in reverse order
    for i in range(len(beads) - 1, -1, -1):
        # Get the head value of the current bead
        head = beads[i]
        # Find the next bead with the same tail value as the current bead's head
        next_bead = i + 1
        if next_bead == len(beads):
            next_bead = 0
        while next_bead != i:
            tail = beads[next_bead]
            # Calculate the energy release from merging the current bead with the next bead
            energy = head * tail * beads[next_bead + 1]
            # Update the maximum energy obtainable from the current bead
            max_energy_from_bead[i] = max(max_energy_from_bead[i], energy)
            # Move to the next bead with the same tail value as the current bead's head
            next_bead += 1
            if next_bead == len(beads):
                next_bead = 0
    # Return the maximum energy obtainable by optimally merging all beads
    return max(max_energy_from_bead.values())

